CREATE OR ALTER PROCEDURE [dbo].[uspPurchaseOrder_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @SupplierId UNIQUEIDENTIFIER = NULL
	, @PurchaseRequestId UNIQUEIDENTIFIER = NULL
	, @Status NVARCHAR(MAX) = NULL
	, @PurchaseOrderNumber NVARCHAR(MAX) = NULL
	, @OrderDate DATETIME = NULL
	, @ExpectedDeliveryDate DATETIME2 = NULL
	, @TotalAmount DECIMAL(18,2) = NULL
	, @Note NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[SupplierId]
			, j1.[Name] AS [SupplierName]
			, t.[PurchaseRequestId]
			, j2.[RequestNo] AS [PurchaseRequestName]
			, t.[OrderDate]
			, t.[Status]
			, t.[TotalAmount]
			, t.[Note]
			, t.[PurchaseOrderNumber]
			, t.[ExpectedDeliveryDate]
			, t.[CreatedDate]
		FROM [dbo].[PurchaseOrder] AS t
		LEFT JOIN [dbo].[Supplier] AS j1 ON j1.[Id] = t.[SupplierId]
		LEFT JOIN [dbo].[PurchaseRequest] AS j2 ON j2.[Id] = t.[PurchaseRequestId]
		WHERE (ISNULL(@SearchText, '') = '' OR t.[PurchaseOrderNumber] LIKE CONCAT('%', @SearchText, '%'))
			AND (@SupplierId IS NULL OR t.[SupplierId] = @SupplierId)
			AND (@PurchaseRequestId IS NULL OR t.[PurchaseRequestId] = @PurchaseRequestId)
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND (ISNULL(@PurchaseOrderNumber, '') = '' OR t.[PurchaseOrderNumber] LIKE CONCAT('%', @PurchaseOrderNumber, '%'))
			AND (@OrderDate IS NULL OR t.[OrderDate] = @OrderDate)
			AND (@ExpectedDeliveryDate IS NULL OR t.[ExpectedDeliveryDate] = @ExpectedDeliveryDate)
			AND (@TotalAmount IS NULL OR t.[TotalAmount] = @TotalAmount)
			AND (ISNULL(@Note, '') = '' OR t.[Note] LIKE CONCAT('%', @Note, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'supplierId' THEN r.[SupplierId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'supplierId' THEN r.[SupplierId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'supplierName' THEN r.[SupplierName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'supplierName' THEN r.[SupplierName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'purchaseRequestId' THEN r.[PurchaseRequestId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'purchaseRequestId' THEN r.[PurchaseRequestId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'purchaseRequestName' THEN r.[PurchaseRequestName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'purchaseRequestName' THEN r.[PurchaseRequestName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'orderDate' THEN r.[OrderDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'orderDate' THEN r.[OrderDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'totalAmount' THEN r.[TotalAmount] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'totalAmount' THEN r.[TotalAmount] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'purchaseOrderNumber' THEN r.[PurchaseOrderNumber] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'purchaseOrderNumber' THEN r.[PurchaseOrderNumber] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'expectedDeliveryDate' THEN r.[ExpectedDeliveryDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'expectedDeliveryDate' THEN r.[ExpectedDeliveryDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
